# SafeTrip SOS installer — colle TOUT ce fichier dans:
#   C:\Users\AZIZ\safetrip\install-sos.ps1
# puis:  powershell -ExecutionPolicy Bypass -File C:\Users\AZIZ\safetrip\install-sos.ps1

$ErrorActionPreference = "Stop"
$root = "C:\Users\AZIZ\safetrip"
$tmpZip = Join-Path $env:TEMP "safetrip-sos-min.zip"
$b64 = @'

'@
[IO.File]::WriteAllBytes($tmpZip, [Convert]::FromBase64String($b64.Trim()))

# Layout attendu dans le zip (fichiers a plat + dossier sos/)
$app = Join-Path $root "app"
New-Item -ItemType Directory -Force -Path (Join-Path $app "lib\features\sos\data") | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $app "lib\features\sos\presentation") | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $app "lib\features\admin\data") | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $app "lib\features\admin\presentation") | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $app "lib\features\home") | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $app "android\app\src\main") | Out-Null

$extract = Join-Path $env:TEMP "safetrip-sos-extract"
if (Test-Path $extract) { Remove-Item $extract -Recurse -Force }
Expand-Archive -Path $tmpZip -DestinationPath $extract -Force

Copy-Item (Join-Path $extract "sos\data\*") (Join-Path $app "lib\features\sos\data\") -Force
Copy-Item (Join-Path $extract "sos\presentation\*") (Join-Path $app "lib\features\sos\presentation\") -Force
Copy-Item (Join-Path $extract "app_shell.dart") (Join-Path $app "lib\features\home\app_shell.dart") -Force
Copy-Item (Join-Path $extract "app.dart") (Join-Path $app "lib\app.dart") -Force
Copy-Item (Join-Path $extract "main.dart") (Join-Path $app "lib\main.dart") -Force
Copy-Item (Join-Path $extract "admin_repository.dart") (Join-Path $app "lib\features\admin\data\admin_repository.dart") -Force
Copy-Item (Join-Path $extract "firebase_admin_repository.dart") (Join-Path $app "lib\features\admin\data\firebase_admin_repository.dart") -Force
Copy-Item (Join-Path $extract "mock_admin_repository.dart") (Join-Path $app "lib\features\admin\data\mock_admin_repository.dart") -Force
Copy-Item (Join-Path $extract "null_admin_repository.dart") (Join-Path $app "lib\features\admin\data\null_admin_repository.dart") -Force
Copy-Item (Join-Path $extract "admin_page.dart") (Join-Path $app "lib\features\admin\presentation\admin_page.dart") -Force
Copy-Item (Join-Path $extract "build.gradle.kts") (Join-Path $app "android\app\build.gradle.kts") -Force
Copy-Item (Join-Path $extract "AndroidManifest.xml") (Join-Path $app "android\app\src\main\AndroidManifest.xml") -Force
Copy-Item (Join-Path $extract "pubspec.yaml") (Join-Path $app "pubspec.yaml") -Force
Copy-Item (Join-Path $extract "firestore.rules") (Join-Path $app "firestore.rules") -Force
Copy-Item (Join-Path $extract "firebase.json") (Join-Path $app "firebase.json") -Force
Copy-Item (Join-Path $extract ".firebaserc") (Join-Path $app ".firebaserc") -Force

Write-Host "OK SOS installe."
Write-Host "sos_button:" (Test-Path (Join-Path $app "lib\features\sos\presentation\sos_button.dart"))
Select-String -Path (Join-Path $app "android\app\build.gradle.kts") -Pattern "isCoreLibraryDesugaringEnabled"
Write-Host ""
Write-Host "Lance:"
Write-Host "  cd C:\Users\AZIZ\safetrip\app"
Write-Host "  flutter pub get"
Write-Host "  flutter run --dart-define=USE_FIREBASE=true -d R5CX50L51JA"
